CREATE TABLE IF NOT EXISTS campaigns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, story TEXT NOT NULL, country TEXT NOT NULL, goal_cents BIGINT NOT NULL CHECK (goal_cents > 0), raised_cents BIGINT NOT NULL DEFAULT 0 CHECK (raised_cents >= 0), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','completed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());